# Sync example:
from typing import Iterator
from dataclasses import dataclass

@dataclass
class Message:
    id: str
    text: str

# stream_iter is Iterable[str] of JSON fragments from SDK streaming response
proxy = HydrationProxy(model_factory=Message, stream_iter=stream_iter)
for event in proxy:
    if event.type == 'MODEL_PARTIAL':
        # show incremental fields, good for low-latency UI updates
        print('partial', event.data)
    elif event.type == 'MODEL_COMPLETE':
        message = event.instance  # dataclass instance
        process(message)
